CREATE OR REPLACE PROCEDURE sp(
    arg1 IN VARCHAR2, 
    arg2 IN NUMBER, 
    arg3 IN VARCHAR2, 
    arg4 IN VARCHAR2
) IS
    v_mascot_count NUMBER;
    v_avg_budget NUMBER;
    v_avg_enrollment NUMBER;
    v_update_count NUMBER := 0;
BEGIN
    SAVEPOINT sp_savepoint;

    SELECT COUNT(*)
    INTO v_mascot_count
    FROM "School"
    WHERE "Mascot" = arg3;

    IF v_mascot_count = 0 THEN
        RAISE_APPLICATION_ERROR(-20002, 'No School record matches the mascot; budget updates skipped');
    END IF;

    SELECT AVG("Budgeted") INTO v_avg_budget FROM "budget";
    SELECT AVG("Enrollment") INTO v_avg_enrollment FROM "School";

    UPDATE "budget"
    SET "total_budget_percent_budgeted" = arg2
    WHERE "Budget_invested_percent" = arg1
      AND "total_budget_percent_budgeted" <= arg2
      AND "Budgeted" > v_avg_budget;

    v_update_count := v_update_count + SQL%ROWCOUNT;

    UPDATE "School"
    SET "Location" = arg4
    WHERE "Mascot" = arg3
      AND "Enrollment" > v_avg_enrollment;

    v_update_count := v_update_count + SQL%ROWCOUNT;

    IF v_update_count = 0 THEN
        RAISE_APPLICATION_ERROR(-20001, 'No matching records were updated');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK TO sp_savepoint;
        RAISE;
END sp;

DECLARE
    v_code NUMBER;
    v_msg VARCHAR2(1000);
BEGIN
    sp('nonexistent', 1, 'nonexistent', 'loc');
EXCEPTION
    WHEN OTHERS THEN
        v_code := SQLCODE;
        v_msg := SQLERRM;
        DBMS_OUTPUT.PUT_LINE(v_code || ' - ' || v_msg);
END;

